package local.gxtodo.qa;
import android.app.Instrumentation;
import android.content.*;
import android.database.Cursor;
import android.database.sqlite.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import com.androidshared.feedback.*;
import org.json.*;
import java.io.*;
import java.lang.reflect.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;

public final class FeedbackQaInstrumentation extends Instrumentation {
 final JSONObject result=new JSONObject();
 final List<Uri> documents=new ArrayList<>();
 Context target; DefaultFeedbackStorage isolated;
 static final String NS="qa_feedback_092", PREFIX="QA_feedback_092_20261114";
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle output=new Bundle();int code=0;try{
  target=getTargetContext();result.put("targetPackage",target.getPackageName()).put("namespace",NS).put("deviceSdk",Build.VERSION.SDK_INT).put("moduleVersion",FeedbackKit.VERSION);
  test();result.put("passed",true);
 }catch(Throwable error){code=1;try{result.put("passed",false).put("error",error.toString());StringWriter trace=new StringWriter();error.printStackTrace(new PrintWriter(trace));result.put("stack",trace.toString());}catch(Exception ignored){}
 }finally{try{cleanup();result.put("isolationCleanup",true);}catch(Throwable error){code=1;try{result.put("cleanupError",error.toString());}catch(Exception ignored){}}}
 try{File out=new File(getContext().getFilesDir(),"result.json");try(FileOutputStream stream=new FileOutputStream(out)){stream.write(result.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}
 output.putString("qa_result",result.toString());finish(code,output);}
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 JSONObject origin() throws Exception{return new JSONObject().put("appId",target.getPackageName()).put("appName","四象限待办·本地版").put("versionName","0.9.2").put("versionCode",15).put("pageLabel","隔离备份QA");}
 JSONObject note(String id,long number,String body,JSONArray assets)throws Exception{return new JSONObject().put("id",id).put("number",number).put("body",body).put("category","experience").put("status","done").put("createdAt",1700000000000L).put("updatedAt",1700000000001L).put("revision",1).put("origin",origin()).put("assetIds",assets).put("inheritedAssetIds",new JSONArray()).put("deletedAt",JSONObject.NULL).put("deleteToken",JSONObject.NULL);}
 JSONObject sequence(long next)throws Exception{return new JSONObject().put("id",FeedbackContract.SEQUENCE_ID).put("nextNumber",next).put("createdAt",1700000000000L).put("updatedAt",1700000000001L).put("revision",1);}
 JSONObject snapshot(DefaultFeedbackStorage store)throws Exception{JSONObject out=new JSONObject();for(String bucket:new String[]{FeedbackStorage.NOTES,FeedbackStorage.DRAFTS,FeedbackStorage.META}){JSONArray arr=new JSONArray();for(JSONObject value:store.all(bucket))arr.put(value);out.put(bucket,arr);}return out;}
 String hash(InputStream in)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] buf=new byte[32768];int n;try(InputStream input=in){while((n=input.read(buf))>0)md.update(buf,0,n);}StringBuilder out=new StringBuilder();for(byte b:md.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 Uri document(String name)throws Exception{ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,name);v.put(MediaStore.MediaColumns.MIME_TYPE,"application/zip");v.put(MediaStore.MediaColumns.RELATIVE_PATH,"Download/GxTodo_QA");Uri uri=target.getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);check(uri!=null,"create QA document");documents.add(uri);return uri;}
 void copyDocument(Uri from,String name)throws Exception{try(InputStream in=target.getContentResolver().openInputStream(from);OutputStream out=new FileOutputStream(new File(getContext().getFilesDir(),name))){byte[] buf=new byte[32768];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}}
 void nonFeedback(File directory,File base,JSONObject out)throws Exception{File[] files=directory.listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparing(File::getName));for(File file:files){if(file.getName().equals("feedback-kit")||file.getName().startsWith("feedback-kit"))continue;if(file.isDirectory())nonFeedback(file,base,out);else out.put(file.getAbsolutePath().substring(base.getAbsolutePath().length()),hash(new FileInputStream(file)));}}
 JSONObject protectedData()throws Exception{JSONObject hashes=new JSONObject();File data=new File(target.getApplicationInfo().dataDir);nonFeedback(new File(data,"files"),data,hashes);nonFeedback(new File(data,"databases"),data,hashes);nonFeedback(new File(data,"shared_prefs"),data,hashes);return hashes;}
 JSONObject sqlite(String name)throws Exception{File file=target.getDatabasePath(name);JSONObject report=new JSONObject().put("file",file.getName()).put("exists",file.isFile()).put("bytes",file.length());try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.OPEN_READONLY)){try(Cursor c=db.rawQuery("PRAGMA integrity_check",null)){check(c.moveToFirst(),"sqlite integrity row");report.put("integrity",c.getString(0));check("ok".equals(c.getString(0)),"sqlite integrity");}for(String table:new String[]{"records","assets","links"})try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM "+table,null)){c.moveToFirst();report.put(table,c.getLong(0));}try(Cursor c=db.rawQuery("SELECT bucket,id,number,state,payload FROM records ORDER BY bucket,id",null)){JSONArray rows=new JSONArray();while(c.moveToNext()){JSONObject row=new JSONObject().put("bucket",c.getString(0)).put("id",c.getString(1)).put("number",c.isNull(2)?JSONObject.NULL:c.getLong(2)).put("state",c.getString(3));JSONObject p=new JSONObject(c.getString(4));if("notes".equals(c.getString(0)))row.put("body",p.optString("body")).put("originVersion",p.getJSONObject("origin").optString("versionName"));rows.put(row);}report.put("rows",rows);}}return report;}
 void test()throws Exception{
  JSONObject protectedBefore=protectedData();
  DefaultFeedbackStorage defaults=new DefaultFeedbackStorage(target);JSONObject defaultsBefore=snapshot(defaults);List<JSONObject> candidates=new ArrayList<>();for(JSONObject n:defaults.all(FeedbackStorage.NOTES))if(PREFIX.equals(n.optString("body")))candidates.add(n);
  check(candidates.size()==1,"exactly one known default QA note");JSONObject ui=candidates.get(0);check(ui.optLong("number")==1&&"done".equals(ui.optString("status")),"UI saved number/status");
  result.put("uiSavedSqlite",sqlite("feedback-kit.db")).put("defaultRecordsBefore",defaults.all(FeedbackStorage.NOTES).size());
  isolated=new DefaultFeedbackStorage(target,NS);check(isolated.all(FeedbackStorage.NOTES).isEmpty()&&isolated.all(FeedbackStorage.DRAFTS).isEmpty()&&isolated.all(FeedbackStorage.META).isEmpty(),"test namespace initially empty");
  File image=new File(target.getCacheDir(),"qa-feedback-092-image.png");Bitmap bmp=Bitmap.createBitmap(8,8,Bitmap.Config.ARGB_8888);bmp.eraseColor(Color.rgb(23,110,94));try(OutputStream out=new FileOutputStream(image)){check(bmp.compress(Bitmap.CompressFormat.PNG,100,out),"PNG fixture");}bmp.recycle();String originalImageHash=hash(new FileInputStream(image));
  final String[] asset={null};isolated.transaction(()->{asset[0]=isolated.importImage(Uri.fromFile(image));JSONArray refs=new JSONArray().put(asset[0]);isolated.put(FeedbackStorage.NOTES,note("qa_saved",1,"QA隔离存储意见",refs));JSONObject draftNote=note("qa_draft_note",2,"QA未提交草稿",refs).put("revision",0);JSONObject draft=new JSONObject().put("id","qa_draft").put("targetId","qa_draft_note").put("baseRevision",0).put("isNew",true).put("createdAt",1700000000000L).put("updatedAt",1700000000001L).put("revision",0).put("note",draftNote).put("assetIds",refs).put("inheritedAssetIds",new JSONArray());isolated.put(FeedbackStorage.DRAFTS,draft);isolated.put(FeedbackStorage.META,sequence(3));return null;});
  JSONObject original=snapshot(isolated);JSONObject disk=sqlite("feedback-kit-"+NS+".db");check(disk.optLong("records")==3&&disk.optLong("assets")==1&&disk.optLong("links")==2,"actual SQLite record/image/link counts");result.put("isolatedSqlite",disk);
  Uri good=document("qa-feedback-092-good.zip");isolated.exportBackup(good);result.put("backupSha256",hash(target.getContentResolver().openInputStream(good)));
  JSONObject changed=isolated.get(FeedbackStorage.NOTES,"qa_saved").put("body","恢复前替换内容").put("revision",2).put("updatedAt",1700000000100L);isolated.put(FeedbackStorage.NOTES,changed);isolated.remove(FeedbackStorage.DRAFTS,"qa_draft");isolated.put(FeedbackStorage.META,sequence(4));check(!original.toString().equals(snapshot(isolated).toString()),"pre-restore state differs");long generation=isolated.generation();isolated.restoreBackup(good);check(original.toString().equals(snapshot(isolated).toString()),"notes drafts sequence roundtrip");check(isolated.generation()>generation,"successful restore generation increments");check(originalImageHash.equals(hash(isolated.openImage(asset[0]))),"restored screenshot bytes");result.put("exportRestore",new JSONObject().put("passed",true).put("notes",1).put("drafts",1).put("meta",1).put("images",1).put("generationAfter",isolated.generation()).put("restoredImageSha256",originalImageHash));
  Uri corrupt=document("qa-feedback-092-corrupt.zip");try(ZipInputStream input=new ZipInputStream(target.getContentResolver().openInputStream(good));ZipOutputStream output=new ZipOutputStream(target.getContentResolver().openOutputStream(corrupt,"wt"))){ZipEntry entry;while((entry=input.getNextEntry())!=null){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buf=new byte[32768];int n;while((n=input.read(buf))>0)bytes.write(buf,0,n);byte[] data=bytes.toByteArray();if("records.jsonl".equals(entry.getName()))data=new String(data,"UTF-8").replace("QA隔离存储意见","QA损坏内容意见").getBytes("UTF-8");output.putNextEntry(new ZipEntry(entry.getName()));output.write(data);output.closeEntry();}}
  JSONObject beforeBad=snapshot(isolated);long beforeBadGeneration=isolated.generation();String rejection=null;try{isolated.restoreBackup(corrupt);}catch(Exception expected){rejection=expected.getMessage();}check(rejection!=null,"corrupt backup rejected");check(beforeBad.toString().equals(snapshot(isolated).toString())&&beforeBadGeneration==isolated.generation(),"corrupt restore keeps all records and generation");check(originalImageHash.equals(hash(isolated.openImage(asset[0]))),"corrupt restore keeps screenshot");result.put("corruptBackup",new JSONObject().put("rejected",true).put("message",rejection).put("recordsUnchanged",true).put("generationUnchanged",true).put("imageUnchanged",true).put("sha256",hash(target.getContentResolver().openInputStream(corrupt))));
  boolean rolledBack=false;try{isolated.transaction(()->{isolated.put(FeedbackStorage.NOTES,isolated.get(FeedbackStorage.NOTES,"qa_saved").put("body","不应提交的事务"));throw new IOException("QA intentional rollback");});}catch(IOException expected){rolledBack=true;}check(rolledBack&&beforeBad.toString().equals(snapshot(isolated).toString()),"SQLite transaction rollback");result.put("transactionRollback",true);
  check(defaultsBefore.toString().equals(snapshot(defaults).toString()),"default feedback unaffected by isolated backup");defaults.remove(FeedbackStorage.NOTES,ui.optString("id"));check(defaults.get(FeedbackStorage.NOTES,ui.optString("id"))==null,"remove only known UI QA note");JSONObject expectedDefault=new JSONObject(defaultsBefore.toString());JSONArray retained=new JSONArray();for(JSONObject n:defaults.all(FeedbackStorage.NOTES))retained.put(n);expectedDefault.put(FeedbackStorage.NOTES,retained);check(expectedDefault.toString().equals(snapshot(defaults).toString()),"default draft/meta unchanged");
  check(protectedBefore.toString().equals(protectedData().toString()),"task account other native data unchanged");result.put("nonFeedbackFilesUnchanged",true).put("protectedFileCount",protectedBefore.length()).put("defaultCleanup",new JSONObject().put("removedExactBody",PREFIX).put("removedId",ui.optString("id")).put("remainingNotes",defaults.all(FeedbackStorage.NOTES).size()).put("draftAndMetaUnchanged",true));
 }
 void cleanup()throws Exception{if(target==null)return;for(Uri uri:documents)target.getContentResolver().delete(uri,null,null);File image=new File(target.getCacheDir(),"qa-feedback-092-image.png");image.delete();if(isolated!=null){Field stateField=DefaultFeedbackStorage.class.getDeclaredField("state");stateField.setAccessible(true);Object state=stateField.get(isolated);Field helperField=state.getClass().getDeclaredField("helper");helperField.setAccessible(true);((SQLiteOpenHelper)helperField.get(state)).close();target.deleteDatabase("feedback-kit-"+NS+".db");File dir=new File(new File(new File(target.getFilesDir(),"feedback-kit"),"namespaces"),NS);deleteInside(dir,dir);check(!target.getDatabasePath("feedback-kit-"+NS+".db").exists()&&!dir.exists(),"test namespace cleaned");}}
 void deleteInside(File root,File value)throws Exception{String p=value.getCanonicalPath(),r=root.getCanonicalPath();check(p.equals(r)||p.startsWith(r+File.separator),"QA cleanup confinement");if(value.isDirectory()){File[] children=value.listFiles();if(children!=null)for(File child:children)deleteInside(root,child);}if(value.exists())check(value.delete(),"QA cleanup file");}
}
